-- Módulo Salão: garçons (staff do restaurante, login próprio via key+senha, criado só pelo dono)
CREATE TABLE IF NOT EXISTS public.garcons (
  id             BIGSERIAL PRIMARY KEY,
  restaurant_id  BIGINT NOT NULL REFERENCES public.restaurants(id) ON DELETE CASCADE,
  nome           TEXT NOT NULL,
  telefone       TEXT,
  login_key      TEXT NOT NULL UNIQUE,
  password_hash  TEXT NOT NULL,
  ativo          BOOLEAN NOT NULL DEFAULT true,
  permissoes     JSONB NOT NULL DEFAULT '{"desconto":false,"cancelar":false,"acrescimo":false}'::jsonb,
  ultimo_acesso_em TIMESTAMPTZ,
  created_at     TIMESTAMPTZ DEFAULT NOW()
);

CREATE INDEX idx_garcons_restaurant ON public.garcons (restaurant_id);

ALTER TABLE public.garcons ENABLE ROW LEVEL SECURITY;

CREATE POLICY garcons_owner ON public.garcons
  FOR ALL USING (
    restaurant_id IN (SELECT id FROM public.restaurants WHERE user_id = auth.uid())
  );

-- Sessão de trabalho do garçom (turno): abre automaticamente na primeira comanda do
-- garçom, encerra quando ele faz "Sair" no portal, com snapshot congelado dos valores
-- (mesmo padrão de caixas.resumo) e aceite/discordância do próprio garçom sobre os
-- valores apurados (vendas, gorjeta, comissão) daquele intervalo.
CREATE TABLE public.garcom_turnos (
  id                    BIGSERIAL PRIMARY KEY,
  restaurant_id         BIGINT NOT NULL REFERENCES public.restaurants(id) ON DELETE CASCADE,
  garcom_id             BIGINT NOT NULL REFERENCES public.garcons(id) ON DELETE CASCADE,
  aberto_em             TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  fechado_em            TIMESTAMPTZ,
  status                TEXT NOT NULL DEFAULT 'aberto' CHECK (status IN ('aberto','fechado')),
  resumo                JSONB,
  conferido_pelo_garcom BOOLEAN,
  observacao_garcom     TEXT
);

CREATE INDEX idx_garcom_turnos_garcom ON public.garcom_turnos (garcom_id);
CREATE INDEX idx_garcom_turnos_restaurant ON public.garcom_turnos (restaurant_id);
CREATE INDEX idx_garcom_turnos_fechado_em ON public.garcom_turnos (fechado_em);

-- Só um turno aberto por garçom por vez.
CREATE UNIQUE INDEX idx_garcom_turnos_um_aberto ON public.garcom_turnos (garcom_id) WHERE status = 'aberto';

ALTER TABLE public.garcom_turnos ENABLE ROW LEVEL SECURITY;

CREATE POLICY garcom_turnos_owner ON public.garcom_turnos
  FOR ALL USING (
    restaurant_id IN (SELECT id FROM public.restaurants WHERE user_id = auth.uid())
  );

-- Módulo Salão: comissão de garçom (configurável, múltiplas por restaurante) + lançamentos por comanda fechada
CREATE TABLE IF NOT EXISTS public.garcom_comissoes_config (
  id             BIGSERIAL PRIMARY KEY,
  restaurant_id  BIGINT NOT NULL REFERENCES public.restaurants(id) ON DELETE CASCADE,
  nome           TEXT NOT NULL,
  tipo           TEXT NOT NULL CHECK (tipo IN ('percentual','fixo')),
  valor          NUMERIC(10,2) NOT NULL,
  base_calculo   TEXT NOT NULL DEFAULT 'total_vendido' CHECK (base_calculo IN ('total_vendido','total_recebido')),
  ativo          BOOLEAN NOT NULL DEFAULT true,
  created_at     TIMESTAMPTZ DEFAULT NOW()
);

CREATE INDEX idx_garcom_comissoes_config_restaurant ON public.garcom_comissoes_config (restaurant_id);

ALTER TABLE public.garcom_comissoes_config ENABLE ROW LEVEL SECURITY;

CREATE POLICY garcom_comissoes_config_owner ON public.garcom_comissoes_config
  FOR ALL USING (
    restaurant_id IN (SELECT id FROM public.restaurants WHERE user_id = auth.uid())
  );

CREATE TABLE IF NOT EXISTS public.garcom_comissoes_lancamentos (
  id             BIGSERIAL PRIMARY KEY,
  garcom_id      BIGINT NOT NULL REFERENCES public.garcons(id) ON DELETE CASCADE,
  order_id       BIGINT NOT NULL REFERENCES public.orders(id) ON DELETE CASCADE,
  config_id      BIGINT REFERENCES public.garcom_comissoes_config(id) ON DELETE SET NULL,
  valor_calculado NUMERIC(10,2) NOT NULL,
  criado_em      TIMESTAMPTZ DEFAULT NOW(),
  UNIQUE (order_id, config_id)
);

CREATE INDEX idx_garcom_comissoes_lancamentos_garcom ON public.garcom_comissoes_lancamentos (garcom_id);

ALTER TABLE public.garcom_comissoes_lancamentos ENABLE ROW LEVEL SECURITY;

CREATE POLICY garcom_comissoes_lancamentos_owner ON public.garcom_comissoes_lancamentos
  FOR ALL USING (
    garcom_id IN (
      SELECT id FROM public.garcons WHERE restaurant_id IN (
        SELECT id FROM public.restaurants WHERE user_id = auth.uid()
      )
    )
  );

-- Registro de repasse (gorjeta + comissão) efetivamente pago ao garçom pelo período
-- consultado no relatório /restaurante/relatorios/garcom. Um repasse por garçom+período
-- evita pagar duas vezes o mesmo intervalo.
CREATE TABLE IF NOT EXISTS public.garcom_repasses (
  id             BIGSERIAL PRIMARY KEY,
  restaurant_id  BIGINT NOT NULL REFERENCES public.restaurants(id) ON DELETE CASCADE,
  garcom_id      BIGINT NOT NULL REFERENCES public.garcons(id) ON DELETE CASCADE,
  periodo_de     TIMESTAMPTZ NOT NULL,
  periodo_ate    TIMESTAMPTZ NOT NULL,
  valor_gorjeta  NUMERIC(10,2) NOT NULL DEFAULT 0,
  valor_comissao NUMERIC(10,2) NOT NULL DEFAULT 0,
  valor_dinheiro NUMERIC(10,2) NOT NULL DEFAULT 0,
  valor_pix      NUMERIC(10,2) NOT NULL DEFAULT 0,
  caixa_id       BIGINT REFERENCES public.caixas(id) ON DELETE SET NULL,
  saida_criado_em TIMESTAMPTZ,
  pago_em        TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  UNIQUE (garcom_id, periodo_de, periodo_ate)
);

CREATE INDEX idx_garcom_repasses_restaurant ON public.garcom_repasses (restaurant_id);
CREATE INDEX idx_garcom_repasses_garcom ON public.garcom_repasses (garcom_id);
CREATE INDEX idx_garcom_repasses_pago_em ON public.garcom_repasses (pago_em);

ALTER TABLE public.garcom_repasses ENABLE ROW LEVEL SECURITY;

CREATE POLICY garcom_repasses_owner ON public.garcom_repasses
  FOR ALL USING (
    restaurant_id IN (SELECT id FROM public.restaurants WHERE user_id = auth.uid())
  );

-- Quando o caixa/estabelecimento abre mesa/comanda direto (sem garçom), guarda o
-- primeiro nome de quem estava logado, pro card da mesa mostrar "Caixa: nome".
ALTER TABLE public.orders ADD COLUMN IF NOT EXISTS aberto_por_nome text;

