1	import React, { useState, useEffect, useMemo } from 'react';
2	import { getRelatorioGarcom, getMinhaEmpresa, registrarRepasseGarcom, estornarRepasseGarcom } from '../../services/restauranteService';
3	import RelatorioNav from './RelatorioNav';
4	import FiltroPeriodo from './FiltroPeriodo';
5	import { fmt, buildRange, printIframe, reportBaseStyle, printFooterScript, defaultFiltroState } from '../../utils/relatorioPrint';
6	
7	const dataHora = (iso) => iso ? new Date(iso).toLocaleString('pt-BR', { timeZone: 'America/Sao_Paulo' }) : '—';
8	const agora = () => new Date().toLocaleString('pt-BR', { timeZone: 'America/Sao_Paulo' });
9	
10	const PAGAMENTO_LABEL = { pix: 'PIX', credit_card: 'Cartão crédito', debit_card: 'Cartão débito', cash: 'Dinheiro' };
11	const traduzFormas = (s) => s ? s.split(' + ').map((f) => PAGAMENTO_LABEL[f] ?? f).join(' + ') : '—';
12	
13	const buildPrintHtml = (garcons, vendas, restauranteNome, label, garcomNome) => {
14	  const rows = garcons.map((g) => `<tr>
15	    <td>${g.nome}</td>
16	    <td class="right bold green">${fmt(g.total_vendido)}</td>
17	    <td class="right">${fmt(g.total_comissao)}</td>
18	    <td class="right">${fmt(g.total_gorjeta)}</td>
19	    <td class="right bold">${fmt(g.total_comissao + g.total_gorjeta)}</td>
20	    <td class="right">${g.comandas_abertas}</td>
21	    <td class="right">${g.comandas_pendentes}</td>
22	  </tr>`).join('');
23	
24	  const vendaRows = (vendas ?? []).map((v) => `<tr>
25	    <td>${dataHora(v.data)}</td>
26	    <td>${v.garcom_nome}</td>
27	    <td>${v.numero_comanda ?? '—'}${v.mesa_numero ? ` (Mesa ${v.mesa_numero})` : ''}</td>
28	    <td>${v.cliente_nome ?? '—'}</td>
29	    <td class="right">${fmt(v.total)}</td>
30	    <td class="right">${fmt(v.gorjeta)}</td>
31	    <td class="right">${fmt(v.taxa_cartao)}</td>
32	    <td>${traduzFormas(v.formas_pagamento)}</td>
33	    <td class="right bold">${fmt(v.total_geral)}</td>
34	  </tr>`).join('');
35	
36	  const vTotal = (vendas ?? []).reduce((s, v) => s + v.total, 0);
37	  const vGorjeta = (vendas ?? []).reduce((s, v) => s + v.gorjeta, 0);
38	  const vTaxaCartao = (vendas ?? []).reduce((s, v) => s + v.taxa_cartao, 0);
39	  const vTotalGeral = (vendas ?? []).reduce((s, v) => s + v.total_geral, 0);
40	  const vendaTotalRow = (vendas ?? []).length ? `<tr>
41	    <td colspan="4" class="bold">Total (${vendas.length})</td>
42	    <td class="right bold">${fmt(vTotal)}</td>
43	    <td class="right bold">${fmt(vGorjeta)}</td>
44	    <td class="right bold">${fmt(vTaxaCartao)}</td>
45	    <td></td>
46	    <td class="right bold">${fmt(vTotalGeral)}</td>
47	  </tr>` : '';
48	
49	  return `<!DOCTYPE html><html><head><meta charset="UTF-8"><title>Relatório Garçom</title>
50	<style>${reportBaseStyle}</style></head><body>
51	<h1>${restauranteNome ?? 'RESTAURANTE'}</h1>
52	<div class="sub">Relatório por Garçom${garcomNome ? ` — ${garcomNome}` : ''} — ${label}</div>
53	<table>
54	  <tr><th>Garçom</th><th class="right">Total Vendido</th><th class="right">Comissão</th><th class="right">Gorjeta</th><th class="right">Total a Receber</th><th class="right">Comandas Abertas</th><th class="right">Pendentes</th></tr>
55	  ${rows || '<tr><td colspan="7">Nenhum garçom com movimento no período.</td></tr>'}
56	</table>
57	<div class="sub" style="margin-top:16px">Detalhamento das vendas</div>
58	<table>
59	  <tr><th>Data/Hora</th><th>Garçom</th><th>Comanda/Mesa</th><th>Cliente</th><th class="right">Total</th><th class="right">Gorjeta</th><th class="right">Taxa Cartão</th><th>Pagamento</th><th class="right">Total Geral</th></tr>
60	  ${vendaRows || '<tr><td colspan="9">Nenhuma venda no período.</td></tr>'}
61	  ${vendaTotalRow}
62	</table>
63	<footer>Emitido em: ${agora()}</footer>
64	${printFooterScript}
65	</body></html>`;
66	};
67	
68	const DestaqueCard = ({ label, nome, valor }) => (
69	  <div className="bg-white dark:bg-[#27272A] border border-[#E4E4E7] dark:border-[#3F3F46] rounded-2xl p-4 min-w-0">
70	    <p className="text-[10px] font-black text-[#A1A1AA] uppercase tracking-widest mb-1 truncate">{label}</p>
71	    <p className="text-sm font-bold text-[#18181B] dark:text-[#F4F4F5] truncate" title={nome ?? undefined}>{nome ?? '—'}</p>
72	    {nome && <p className="text-xs text-[#71717A] dark:text-[#A1A1AA] mt-0.5 truncate" title={valor ?? undefined}>{valor}</p>}
73	  </div>
74	);
75	
76	const SORT_CAMPOS = [
77	  { id: 'total_vendido', label: 'Venda' },
78	  { id: 'total_gorjeta', label: 'Gorjeta' },
79	  { id: 'total_comissao', label: 'Comissão' },
80	];
81	
82	const RelatorioGarcom = () => {
83	  const [restauranteNome, setRestauranteNome] = useState('');
84	  const [filtro, setFiltro] = useState(defaultFiltroState());
85	  const [garcons, setGarcons] = useState(null);
86	  const [vendas, setVendas] = useState([]);
87	  const [turnos, setTurnos] = useState([]);
88	  const [label, setLabel] = useState('');
89	  const [garcomId, setGarcomId] = useState('');
90	  const [loading, setLoading] = useState(false);
91	  const [erro, setErro] = useState(null);
92	  const [rangeAtual, setRangeAtual] = useState(null);
93	  const [marcandoPago, setMarcandoPago] = useState(null);
94	  const [repasseModal, setRepasseModal] = useState(null);
95	  const [valorDinheiro, setValorDinheiro] = useState('');
96	  const [valorPix, setValorPix] = useState('');
97	  const [busca, setBusca] = useState('');
98	  const [sortCampo, setSortCampo] = useState('total_vendido');
99	  const [expandido, setExpandido] = useState(null);
100	
101	  useEffect(() => {
102	    getMinhaEmpresa().then((d) => setRestauranteNome(d.empresa?.name ?? '')).catch(() => {});
103	  }, []);
104	
105	  const buscar = async () => {
106	    const range = buildRange(filtro.modo, filtro.dia, filtro.mes, filtro.ano, filtro.periodoIni, filtro.periodoFim);
107	    if (!range) return;
108	    setLoading(true); setErro(null);
109	    try {
110	      const d = await getRelatorioGarcom(range.de, range.ate);
111	      setGarcons(d.garcons ?? []);
112	      setVendas(d.vendas ?? []);
113	      setTurnos(d.turnos ?? []);
114	      setLabel(range.label);
115	      setRangeAtual(range);
116	    } catch (e) { setErro(e.message); }
117	    finally { setLoading(false); }
118	  };
119	
120	  const abrirRepasse = (g) => {
121	    setErro(null);
122	    setRepasseModal(g);
123	    setValorDinheiro((g.total_gorjeta + g.total_comissao).toFixed(2));
124	    setValorPix('0.00');
125	  };
126	
127	  const confirmarRepasse = async () => {
128	    if (!rangeAtual || !repasseModal) return;
129	    const total = repasseModal.total_gorjeta + repasseModal.total_comissao;
130	    const vd = Number(valorDinheiro || 0);
131	    const vp = Number(valorPix || 0);
132	    if (Math.abs(vd + vp - total) > 0.01) {
133	      setErro(`Soma dos valores (${fmt(vd + vp)}) não bate com o total a repassar (${fmt(total)})`);
134	      return;
135	    }
136	    setMarcandoPago(repasseModal.garcom_id);
137	    try {
138	      await registrarRepasseGarcom(repasseModal.garcom_id, {
139	        de: rangeAtual.de,
140	        ate: rangeAtual.ate,
141	        valor_gorjeta: repasseModal.total_gorjeta,
142	        valor_comissao: repasseModal.total_comissao,
143	        valor_dinheiro: vd,
144	        valor_pix: vp,
145	      });
146	      setRepasseModal(null);
147	      await buscar();
148	    } catch (e) { setErro(e.message); }
149	    finally { setMarcandoPago(null); }
150	  };
151	
152	  const estornarRepasse = async (g) => {
153	    if (!window.confirm(`Reverter o repasse de ${g.nome} pra "não pago"? Se teve baixa em dinheiro no caixa, ela também é estornada.`)) return;
154	    setMarcandoPago(g.garcom_id);
155	    try {
156	      await estornarRepasseGarcom(g.repasse.id);
157	      await buscar();
158	    } catch (e) { setErro(e.message); }
159	    finally { setMarcandoPago(null); }
160	  };
161	
162	  useEffect(() => { buscar(); }, []); // eslint-disable-line
163	
164	  const garconsFiltrados = useMemo(() => {
165	    let lista = garcomId ? (garcons ?? []).filter((g) => String(g.garcom_id) === garcomId) : (garcons ?? []);
166	    if (busca.trim()) lista = lista.filter((g) => g.nome.toLowerCase().includes(busca.trim().toLowerCase()));
167	    return [...lista].sort((a, b) => (b[sortCampo] ?? 0) - (a[sortCampo] ?? 0));
168	  }, [garcons, garcomId, busca, sortCampo]);
169	  const vendasFiltradas = garcomId ? vendas.filter((v) => String(v.garcom_id) === garcomId) : vendas;
170	  const turnosFiltrados = garcomId ? turnos.filter((t) => String(t.garcom_id) === garcomId) : turnos;
171	  const nomeGarcomPorId = useMemo(() => Object.fromEntries((garcons ?? []).map((g) => [g.garcom_id, g.nome])), [garcons]);
172	  const garcomSelecionadoNome = garcomId ? (garcons ?? []).find((g) => String(g.garcom_id) === garcomId)?.nome : null;
173	
174	  const totalVendido = garconsFiltrados.reduce((s, g) => s + g.total_vendido, 0);
175	  const totalComissao = garconsFiltrados.reduce((s, g) => s + g.total_comissao, 0);
176	  const totalGorjeta = garconsFiltrados.reduce((s, g) => s + g.total_gorjeta, 0);
177	  const totalAReceber = totalComissao + totalGorjeta;
178	
179	  const quemVendeuMais = useMemo(() => {
180	    const comVenda = (garcons ?? []).filter((g) => g.total_vendido > 0);
181	    return comVenda.length ? [...comVenda].sort((a, b) => b.total_vendido - a.total_vendido)[0] : null;
182	  }, [garcons]);
183	  const quemGanhouMaisGorjeta = useMemo(() => {
184	    const comGorjeta = (garcons ?? []).filter((g) => g.total_gorjeta > 0);
185	    return comGorjeta.length ? [...comGorjeta].sort((a, b) => b.total_gorjeta - a.total_gorjeta)[0] : null;
186	  }, [garcons]);
187	
188	  return (
189	    <div className="min-h-screen bg-[#FAFAFA] dark:bg-[#18181B]">
190	      <RelatorioNav titulo="Garçom" />
191	      <main className="p-6 max-w-5xl mx-auto space-y-4">
192	        <FiltroPeriodo
193	          filtro={filtro} setFiltro={setFiltro} onBuscar={buscar} loading={loading}
194	          podeImprimir={!!garcons} onImprimir={() => printIframe(buildPrintHtml(garconsFiltrados, vendasFiltradas, restauranteNome, label, garcomSelecionadoNome))}
195	        />
196	
197	        {garcons && garcons.length > 0 && (
198	          <div className="bg-white dark:bg-[#27272A] rounded-2xl border border-[#E4E4E7] dark:border-[#3F3F46] p-4 flex flex-wrap gap-3 items-end">
199	            <div className="flex flex-col gap-1">
200	              <label className="text-xs font-bold text-[#71717A] dark:text-[#A1A1AA] uppercase tracking-widest">Buscar por nome</label>
201	              <input value={busca} onChange={(e) => setBusca(e.target.value)} placeholder="Nome do garçom..."
202	                className="border border-[#E4E4E7] dark:border-[#3F3F46] bg-white dark:bg-[#18181B] text-[#18181B] dark:text-[#F4F4F5] rounded-xl px-3 py-2 text-sm focus:outline-none focus:border-[#FF441F] min-w-[180px]" />
203	            </div>
204	            <div className="flex flex-col gap-1">
205	              <label className="text-xs font-bold text-[#71717A] dark:text-[#A1A1AA] uppercase tracking-widest">Garçom</label>
206	              <select value={garcomId} onChange={(e) => setGarcomId(e.target.value)}
207	                className="border border-[#E4E4E7] dark:border-[#3F3F46] bg-white dark:bg-[#18181B] text-[#18181B] dark:text-[#F4F4F5] rounded-xl px-3 py-2 text-sm focus:outline-none focus:border-[#FF441F] min-w-[200px]">
208	                <option value="">Todos os garçons</option>
209	                {garcons.map((g) => <option key={g.garcom_id} value={g.garcom_id}>{g.nome}</option>)}
210	              </select>
211	            </div>
212	            <div className="flex flex-col gap-1">
213	              <label className="text-xs font-bold text-[#71717A] dark:text-[#A1A1AA] uppercase tracking-widest">Ordenar por</label>
214	              <div className="flex gap-1 bg-[#F4F4F5] dark:bg-[#3F3F46] p-1 rounded-xl">
215	                {SORT_CAMPOS.map((s) => (
216	                  <button key={s.id} onClick={() => setSortCampo(s.id)}
217	                    className={`px-3 py-1.5 text-xs font-bold rounded-lg transition-colors ${sortCampo === s.id ? 'bg-white dark:bg-[#27272A] text-[#18181B] dark:text-[#F4F4F5] shadow-sm' : 'text-[#71717A] dark:text-[#A1A1AA] hover:text-[#27272A] dark:hover:text-[#F4F4F5]'}`}>
218	                    {s.label}
219	                  </button>
220	                ))}
221	              </div>
222	            </div>
223	            {garcomId && (
224	              <button onClick={() => printIframe(buildPrintHtml(garconsFiltrados, vendasFiltradas, restauranteNome, label, garcomSelecionadoNome))}
225	                className="flex items-center gap-2 px-4 py-2 bg-[#18181B] text-white text-sm font-bold rounded-xl hover:bg-[#27272A] transition-colors">
226	                Imprimir só {garcomSelecionadoNome}
227	              </button>
228	            )}
229	          </div>
230	        )}
231	
232	        {erro && <p className="text-sm text-red-600 dark:text-red-400 bg-red-50 dark:bg-red-950/40 px-3 py-2 rounded-xl">{erro}</p>}
233	
234	        {garcons && (
235	          <>
236	            <div className="grid grid-cols-2 md:grid-cols-4 gap-3">
237	              <div className="bg-white dark:bg-[#27272A] border border-green-200 dark:border-green-800 rounded-2xl p-4 text-center min-w-0">
238	                <p className="text-[10px] font-black text-green-600 dark:text-green-400 uppercase tracking-widest mb-1 truncate">Total Vendido</p>
239	                <p className="text-lg sm:text-2xl font-black text-green-700 dark:text-green-400 truncate" title={fmt(totalVendido)}>{fmt(totalVendido)}</p>
240	              </div>
241	              <div className="bg-white dark:bg-[#27272A] border border-[#E4E4E7] dark:border-[#3F3F46] rounded-2xl p-4 text-center min-w-0">
242	                <p className="text-[10px] font-black text-[#71717A] dark:text-[#A1A1AA] uppercase tracking-widest mb-1 truncate">Comissão Total</p>
243	                <p className="text-lg sm:text-2xl font-black text-[#18181B] dark:text-[#F4F4F5] truncate" title={fmt(totalComissao)}>{fmt(totalComissao)}</p>
244	              </div>
245	              <div className="bg-white dark:bg-[#27272A] border border-[#E4E4E7] dark:border-[#3F3F46] rounded-2xl p-4 text-center min-w-0">
246	                <p className="text-[10px] font-black text-[#71717A] dark:text-[#A1A1AA] uppercase tracking-widest mb-1 truncate">Gorjeta Total</p>
247	                <p className="text-lg sm:text-2xl font-black text-[#18181B] dark:text-[#F4F4F5] truncate" title={fmt(totalGorjeta)}>{fmt(totalGorjeta)}</p>
248	              </div>
