2	import { SupabaseService } from '../supabase/supabase.service';
3	
4	// Sessão de trabalho do garçom ("turno"): abre sozinha quando ele abre a primeira comanda
5	// (ver garantirTurnoAberto, chamado por SalaoService.abrirComanda) e fecha quando ele faz
6	// "Sair" no portal (ver SalaoController). Não tem nenhuma relação com garcons.active_session_id
7	// (isso é só lock de dispositivo/login) — aqui é turno de trabalho mesmo, com vendas/gorjeta/
8	// comissão apuradas no intervalo [aberto_em, fechado_em] e congeladas em `resumo` no fechamento,
9	// igual já é feito com caixas.resumo.
10	@Injectable()
11	export class GarcomTurnoService {
12	  constructor(private supabase: SupabaseService) {}
13	
14	  async turnoAtivo(garcomId: number) {
15	    const { data } = await this.supabase.client
16	      .from('garcom_turnos')
17	      .select('*')
18	      .eq('garcom_id', garcomId)
19	      .eq('status', 'aberto')
20	      .maybeSingle();
21	    return data ?? null;
22	  }
23	
24	  async garantirTurnoAberto(garcomId: number, restaurantId: number) {
25	    const ativo = await this.turnoAtivo(garcomId);
26	    if (ativo) return ativo;
27	
28	    const { data, error } = await this.supabase.client
29	      .from('garcom_turnos')
30	      .insert({ restaurant_id: restaurantId, garcom_id: garcomId })
31	      .select()
32	      .single();
33	
34	    if (error) {
35	      // Corrida rara (duas comandas abertas quase ao mesmo tempo) — o índice único
36	      // (garcom_id) WHERE status='aberto' garante que só um insert vingou; pega esse.
37	      const existente = await this.turnoAtivo(garcomId);
38	      if (existente) return existente;
39	      throw error;
40	    }
41	    return data;
42	  }
43	
44	  // Vendas/gorjeta/comissão do garçom no intervalo — mesmo recorte que
45	  // RestauranteService.getRelatorioGarcom já usa (orders.created_at no intervalo,
46	  // status='paga'), só que restrito a um garçom só.
47	  async resumoTurno(garcomId: number, restaurantId: number, desde: string, ate: string) {
48	    const { data: pedidos } = await this.supabase.client
49	      .from('orders')
50	      .select('id, total, status, gorjeta_valor, created_at, numero_comanda, cliente_mesa_nome, mesas(numero, nome)')
51	      .eq('restaurant_id', restaurantId)
52	      .eq('canal', 'presencial')
53	      .eq('garcom_id', garcomId)
54	      .gte('created_at', desde)
55	      .lte('created_at', ate);
56	
57	    const pedidosPagos = ((pedidos ?? []) as any[]).filter((p) => p.status === 'paga');
58	    const orderIds = pedidosPagos.map((p) => p.id);
59	
60	    const { data: comissoes } = orderIds.length
61	      ? await this.supabase.client
62	          .from('garcom_comissoes_lancamentos')
63	          .select('order_id, valor_calculado')
64	          .in('order_id', orderIds)
65	      : { data: [] as any[] };
66	
67	    const { data: itens } = orderIds.length
68	      ? await this.supabase.client
69	          .from('order_items')
70	          .select('order_id, quantity, unit_price, products(name)')
71	          .in('order_id', orderIds)
72	      : { data: [] as any[] };
73	
74	    const total_vendido = pedidosPagos.reduce((s, p) => s + (p.total ?? 0), 0);
75	    const total_gorjeta = pedidosPagos.reduce((s, p) => s + (p.gorjeta_valor ?? 0), 0);
76	    const total_comissao = ((comissoes ?? []) as any[]).reduce((s, c) => s + (c.valor_calculado ?? 0), 0);
77	
78	    // Comandas ainda abertas do garçom (não filtra por intervalo — é o estado atual, igual
79	    // comandas_abertas do preview de encerramento) — pra dar visibilidade de quanto ainda
80	    // está "em jogo": total em aberto, e a projeção de gorjeta/comissão SE tudo isso for
81	    // pago do jeito que está agora (mesmas regras usadas de verdade no fechamento da
82	    // comanda — ver lancarComissoes/sugestaoGorjeta em salao-pdv.service.ts).
83	    const comandasAbertas = await this.comandasAbertasDoGarcom(garcomId);
84	    const total_em_aberto = comandasAbertas.reduce((s, c: any) => s + (c.total ?? 0), 0);
85	
86	    const { data: restaurante } = await this.supabase.client
87	      .from('restaurants')
88	      .select('gorjeta_percentual')
89	      .eq('id', restaurantId)
90	      .maybeSingle();
91	    const gorjetaPercentual = (restaurante as any)?.gorjeta_percentual ?? 0;
92	    const gorjeta_projetada_em_aberto = parseFloat(((total_em_aberto * gorjetaPercentual) / 100).toFixed(2));
93	
94	    const { data: configsComissao } = await this.supabase.client
95	      .from('garcom_comissoes_config')
96	      .select('tipo, valor')
97	      .eq('restaurant_id', restaurantId)
98	      .eq('ativo', true);
99	    let comissao_projetada_em_aberto = 0;
100	    for (const c of comandasAbertas as any[]) {
101	      for (const cfg of (configsComissao ?? []) as any[]) {
102	        comissao_projetada_em_aberto += cfg.tipo === 'percentual' ? ((c.total ?? 0) * cfg.valor) / 100 : cfg.valor;
103	      }
104	    }
105	    comissao_projetada_em_aberto = parseFloat(comissao_projetada_em_aberto.toFixed(2));
106	
107	    const vendas = pedidosPagos
108	      .map((p) => ({
109	        order_id: p.id,
110	        numero_comanda: p.numero_comanda,
111	        mesa_numero: p.mesas?.numero ?? null,
112	        mesa_nome: p.mesas?.nome ?? null,
113	        cliente_nome: p.cliente_mesa_nome ?? null,
114	        data: p.created_at,
115	        total: p.total ?? 0,
116	        gorjeta: p.gorjeta_valor ?? 0,
117	      }))
118	      .sort((a, b) => new Date(a.data).getTime() - new Date(b.data).getTime());
119	
120	    const itens_vendidos = ((itens ?? []) as any[]).map((i) => ({
121	      order_id: i.order_id,
122	      product_name: i.products?.name ?? null,
123	      quantity: i.quantity,
124	      unit_price: i.unit_price,
125	    }));
126	
127	    return {
128	      total_vendido,
129	      total_em_aberto,
130	      total_gorjeta,
131	      gorjeta_projetada: parseFloat((total_gorjeta + gorjeta_projetada_em_aberto).toFixed(2)),
132	      total_comissao,
133	      comissao_projetada: parseFloat((total_comissao + comissao_projetada_em_aberto).toFixed(2)),
134	      vendas,
135	      itens_vendidos,
136	    };
137	  }
138	
139	  private async comandasAbertasDoGarcom(garcomId: number) {
140	    const { data } = await this.supabase.client
141	      .from('orders')
142	      .select('id, numero_comanda, mesa_id, cliente_mesa_nome, status, total, mesas(numero, nome)')
143	      .eq('garcom_id', garcomId)
144	      .eq('canal', 'presencial')
145	      .in('status', ['aberta', 'fechada_garcom']);
146	    return data ?? [];
147	  }
148	
149	  async previewEncerramento(garcomId: number, restaurantId: number) {
150	    const turno = await this.turnoAtivo(garcomId);
151	    if (!turno) throw new NotFoundException('Nenhuma sessão de trabalho aberta');
152	
153	    const [resumo, comandas_abertas] = await Promise.all([
154	      this.resumoTurno(garcomId, restaurantId, turno.aberto_em, new Date().toISOString()),
155	      this.comandasAbertasDoGarcom(garcomId),
156	    ]);
157	
158	    return { turno, resumo, comandas_abertas };
159	  }
160	
161	  async encerrarTurno(garcomId: number, restaurantId: number, body: { conferido: boolean; observacao?: string }) {
162	    const turno = await this.turnoAtivo(garcomId);
163	    if (!turno) throw new NotFoundException('Nenhuma sessão de trabalho aberta');
164	
165	    const fechado_em = new Date().toISOString();
166	    const [resumoFinanceiro, comandas_mantidas_abertas] = await Promise.all([
167	      this.resumoTurno(garcomId, restaurantId, turno.aberto_em, fechado_em),
168	      this.comandasAbertasDoGarcom(garcomId),
169	    ]);
170	
171	    const resumo = { ...resumoFinanceiro, comandas_mantidas_abertas };
172	
173	    const { data, error } = await this.supabase.client
174	      .from('garcom_turnos')
175	      .update({
176	        status: 'fechado',
177	        fechado_em,
178	        resumo,
179	        conferido_pelo_garcom: body.conferido,
180	        observacao_garcom: body.observacao?.trim() || null,
181	      })
182	      .eq('id', turno.id)
183	      .select()
184	      .single();
185	    if (error) throw error;
186	    return data;
187	  }
188	
189	  async historicoTurnos(garcomId: number, de: string, ate: string) {
190	    const { data, error } = await this.supabase.client
191	      .from('garcom_turnos')
192	      .select('*')
193	      .eq('garcom_id', garcomId)
194	      .eq('status', 'fechado')
195	      .gte('fechado_em', de)
196	      .lte('fechado_em', ate)
197	      .order('fechado_em', { ascending: false });
198	    if (error) throw error;
199	    return data ?? [];
