const nomeGarcom = new Map<number, string>((garcons ?? []).map((g: any) => [g.id, g.nome]));
const vendas = (pedidos ?? [])
  .filter((p: any) => p.status === 'paga')
  .map((p: any) => {
    const pagamentos = pagamentosPorComanda.get(p.id) ?? [];
    const taxa_cartao = pagamentos.reduce((s, pg) => s + (pg.taxa_cartao_valor ?? 0), 0);
    const formas_pagamento = pagamentos.length
      ? [...new Set(pagamentos.map((pg) => pg.forma_pagamento))].join(' + ')
      : null;
    const gorjeta = p.gorjeta_valor ?? 0;
    return {
      order_id: p.id,
      numero_comanda: p.numero_comanda,
      garcom_id: p.garcom_id,
      garcom_nome: nomeGarcom.get(p.garcom_id) ?? '—',
      mesa_numero: p.mesas?.numero ?? null,
      mesa_nome: p.mesas?.nome ?? null,
      // Nome digitado nessa comanda em específico é o dado real da venda — vem
      // primeiro. `customers.name` só serve de fallback: se o telefone bater com
      // um cliente já cadastrado (resolverOuCriarClienteComanda, salao.service.ts),
      // o customer_id é reaproveitado mas o cadastro NUNCA é renomeado, então usar
      // o nome do cadastro aqui mostrava o nome de uma comanda antiga (ex.: garçom
      // reaproveitando o mesmo telefone pra clientes diferentes) em vez do cliente
      // de fato atendido nesta venda.
      cliente_nome: p.cliente_mesa_nome ?? p.customers?.name ?? null,
      data: p.created_at,
      total: p.total ?? 0,
      gorjeta,
      taxa_cartao,
      formas_pagamento,
      total_geral: (p.total ?? 0) + gorjeta + taxa_cartao,
    };
  })
  .sort((a, b) => new Date(a.data).getTime() - new Date(b.data).getTime());

// Sessões (turnos) de trabalho fechadas no período — pra tela do dono mostrar se o
// garçom já conferiu/aceitou os valores daquele intervalo (ver garcom-turno.service.ts).
const { data: turnos } = await this.supabase.client
  .from('garcom_turnos')
  .select('id, garcom_id, aberto_em, fechado_em, resumo, conferido_pelo_garcom, observacao_garcom')
  .eq('restaurant_id', restaurantId)
  .eq('status', 'fechado')
  .gte('fechado_em', de)
  .lte('fechado_em', ate)
  .order('fechado_em', { ascending: false });

-- Trilha de auditoria pras trocas de email/senha de outros usuários feitas
-- por admin (suporte manual). Só o backend (service_role, ignora RLS) grava
-- — sem policy de INSERT/UPDATE/DELETE pra authenticated/anon, pra ninguém
-- conseguir forjar uma linha de auditoria client-side.
CREATE TABLE IF NOT EXISTS public.admin_audit_log (
    id BIGSERIAL PRIMARY KEY,
    admin_user_id UUID REFERENCES public.user_profiles(id) ON DELETE SET NULL,
    target_user_id UUID REFERENCES public.user_profiles(id) ON DELETE SET NULL,
    acao TEXT NOT NULL,
    detalhes JSONB NOT NULL DEFAULT '{}'::jsonb,
    criado_em TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS idx_admin_audit_log_target ON public.admin_audit_log(target_user_id);
CREATE INDEX IF NOT EXISTS idx_admin_audit_log_admin ON public.admin_audit_log(admin_user_id);
CREATE INDEX IF NOT EXISTS idx_admin_audit_log_criado_em ON public.admin_audit_log(criado_em DESC);

ALTER TABLE public.admin_audit_log ENABLE ROW LEVEL SECURITY;

CREATE POLICY "admin_ver_auditoria" ON public.admin_audit_log
    FOR SELECT TO authenticated USING (public.has_role('admin'));
